CREATE TABLE pacientes (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL CHECK(length(trim(nombre)) > 0));
CREATE TABLE medicos (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL UNIQUE, especialidad TEXT NOT NULL);
CREATE TABLE citas (id INTEGER PRIMARY KEY AUTOINCREMENT, paciente_id INTEGER NOT NULL REFERENCES pacientes(id), medico_id INTEGER NOT NULL REFERENCES medicos(id), fecha TEXT NOT NULL, hora TEXT NOT NULL, creado_en TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(medico_id, fecha, hora));
